mapper.select:
SELECT pc.COSTING_ID AS costing_id, pc.PRODUCT_ID AS product_id, pc.PRODUCT_CODE AS product_code, pc.PRODUCT_NAME AS product_name, pc.COSTING_PERIOD AS costing_period, pc.COSTING_METHOD AS costing_method, CASE pc.COSTING_METHOD WHEN 1 THEN '品种法' WHEN 2 THEN '分批法' WHEN 3 THEN '分步法' ELSE '未知' END AS costing_method_name, pc.DIRECT_MATERIAL AS direct_material, pc.DIRECT_LABOR AS direct_labor, pc.MANUFACTURING_OVERHEAD AS manufacturing_overhead, pc.TOTAL_COST AS total_cost, pc.UNIT_COST AS unit_cost, pc.PRODUCTION_QUANTITY AS production_quantity, pc.COSTING_STATUS AS costing_status, CASE pc.COSTING_STATUS WHEN 1 THEN '核算中' WHEN 2 THEN '已完成' ELSE '未知' END AS status_name, pc.CREATE_TIME AS create_time, pc.UPDATE_TIME AS update_time FROM T_PRODUCT_COST pc WHERE pc.IS_DELETED = 0 AND pc.BOOK_ID = #{param.bookId} AND pc.TENANT_ID = #{param.tenantId}
AND pc.PRODUCT_CODE LIKE '%' || #{param.productCode} || '%'
AND pc.PRODUCT_NAME LIKE '%' || #{param.productName} || '%'
AND pc.COSTING_PERIOD = #{param.costingPeriod}
AND pc.COSTING_METHOD = #{param.costingMethod} AND pc.COSTING_STATUS = #{param.costingStatus} ORDER BY pc.CREATE_TIME DESC

SELECT pc.PRODUCT_CODE AS product_code, pc.PRODUCT_NAME AS product_name, COALESCE(SUM(pc.TOTAL_COST), 0) AS total_cost, COALESCE(SUM(pc.DIRECT_MATERIAL), 0) AS direct_material, COALESCE(SUM(pc.DIRECT_LABOR), 0) AS direct_labor, COALESCE(SUM(pc.MANUFACTURING_OVERHEAD), 0) AS manufacturing_overhead, COALESCE(AVG(pc.UNIT_COST), 0) AS avg_unit_cost, COUNT(*) AS costing_count FROM T_PRODUCT_COST pc WHERE pc.IS_DELETED = 0 AND pc.BOOK_ID = #{param.bookId} AND pc.TENANT_ID = #{param.tenantId}
AND pc.COSTING_PERIOD = #{param.costingPeriod}
GROUP BY pc.PRODUCT_CODE, pc.PRODUCT_NAME ORDER BY total_cost DESC

SELECT pc.PRODUCT_ID AS product_id, MAX(pc.PRODUCT_CODE) AS product_code, MAX(pc.PRODUCT_NAME) AS product_name, COALESCE(SUM(pc.DIRECT_MATERIAL), 0) AS direct_material, COALESCE(SUM(pc.DIRECT_LABOR), 0) AS direct_labor, COALESCE(SUM(pc.MANUFACTURING_OVERHEAD), 0) AS manufacturing_overhead, COALESCE(SUM(pc.TOTAL_COST), 0) AS total_cost, CASE WHEN COALESCE(SUM(pc.TOTAL_COST), 0) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(pc.DIRECT_MATERIAL), 0) * 100.0 / SUM(pc.TOTAL_COST), 2) END AS material_ratio, CASE WHEN COALESCE(SUM(pc.TOTAL_COST), 0) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(pc.DIRECT_LABOR), 0) * 100.0 / SUM(pc.TOTAL_COST), 2) END AS labor_ratio, CASE WHEN COALESCE(SUM(pc.TOTAL_COST), 0) = 0 THEN 0 ELSE ROUND(COALESCE(SUM(pc.MANUFACTURING_OVERHEAD), 0) * 100.0 / SUM(pc.TOTAL_COST), 2) END AS overhead_ratio FROM T_PRODUCT_COST pc WHERE pc.IS_DELETED = 0 AND pc.BOOK_ID = #{param.bookId} AND pc.TENANT_ID = #{param.tenantId}
AND pc.COSTING_PERIOD = #{param.costingPeriod}
GROUP BY pc.PRODUCT_ID ORDER BY total_cost DESC

SELECT b.BUDGET_ID AS budget_id, b.BUDGET_NAME AS budget_name, b.PRODUCT_ID AS product_id, b.PRODUCT_NAME AS product_name, b.BUDGET_PERIOD AS budget_period, b.BUDGET_AMOUNT AS budget_amount, b.ACTUAL_AMOUNT AS actual_amount, b.VARIANCE_AMOUNT AS variance_amount, b.EXECUTION_RATE AS execution_rate, b.BUDGET_STATUS AS budget_status, CASE b.BUDGET_STATUS WHEN 'WITHIN_BUDGET' THEN '预算内' WHEN 'NEAR_BUDGET' THEN '接近预算' WHEN 'OVER_BUDGET' THEN '超预算' ELSE '未知' END AS budget_status_name, b.CREATE_TIME AS create_time FROM T_BUDGET_EXECUTION b WHERE b.IS_DELETED = 0 AND b.BOOK_ID = #{param.bookId} AND b.TENANT_ID = #{param.tenantId}
AND b.BUDGET_PERIOD = #{param.costingPeriod}
ORDER BY b.BUDGET_PERIOD DESC, b.PRODUCT_ID ASC

SELECT r.REPORT_ID AS report_id, r.REPORT_NAME AS report_name, r.REPORT_TYPE AS report_type, r.REPORT_TYPE_NAME AS report_type_name, r.REPORT_PERIOD AS report_period, r.GENERATE_TIME AS generate_time, r.GENERATOR_NAME AS generator_name, r.FILE_SIZE AS file_size, r.GENERATE_STATUS AS generate_status, r.REPORT_DESC AS report_desc, r.CREATE_TIME AS create_time FROM T_COST_REPORT r WHERE r.IS_DELETED = 0 AND r.BOOK_ID = #{param.bookId} AND r.TENANT_ID = #{param.tenantId}
AND r.REPORT_TYPE = #{param.reportType}
ORDER BY r.GENERATE_TIME DESC, r.REPORT_ID DESC
